// Generated by scripts/content.mjs before every start and build: for each
// image in public/uploads it lists the resized WebP variants and dimensions.
import manifest from "../content/_images.json";

/**
 * Resolve an uploaded image path ("/uploads/x.png") to what <img> needs.
 * Returns null when there is no image. If the path is not in the manifest
 * (for example an external URL), the original is used at every size.
 */
export function image(path, alt = "") {
  if (!path) return null;
  const entry = manifest[path];
  if (!entry) return { sm: path, lg: path, srcSet: undefined, alt };
  return {
    sm: entry.sm,
    lg: entry.lg,
    srcSet: `${entry.sm} ${entry.smWidth}w, ${entry.lg} ${entry.lgWidth}w`,
    width: entry.lgWidth,
    height: entry.lgHeight,
    alt,
  };
}
